import{_ as e,H as l,f as a,i as d}from"./chunks/framework.DLd0CbzH.js";const x=JSON.parse('{"title":"BRD — Agelto","description":"","frontmatter":{"type":"brd","tags":["agelto","brd","requirements","ai","procurement-tech"],"created":"2026-05-31T00:00:00.000Z","updated":"2026-06-13T00:00:00.000Z"},"headers":[],"relativePath":"03_Dev/BRD (Agelto).md","filePath":"03_Dev/BRD (Agelto).md"}'),r={name:"03_Dev/BRD (Agelto).md"};function n(i,t,s,o,g,h){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="brd-—-agelto" tabindex="-1">BRD — Agelto <a class="header-anchor" href="#brd-—-agelto" aria-label="Permalink to &quot;BRD — Agelto&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">Назначение</p><p>Что должна делать система (ЧТО, не КАК). Архитектура и реализация — в [[Architecture_Agelto]]. Статус разработки — в [[Dev_Status]].</p></div><div class="info custom-block github-alert"><p class="custom-block-title">Связанные документы</p><p>← [[Agelto]] | → [[Architecture_Agelto]] | → [[Dev_Status]] | → [[01_Concept_and_Monetization (Agelto)]] | → [[Открытые вопросы (Agelto)]] | → [[Risk_Register (Agelto)]]</p></div><hr><h2 id="_1-цель-системы" tabindex="-1">1. Цель системы <a class="header-anchor" href="#_1-цель-системы" aria-label="Permalink to &quot;1. Цель системы&quot;">​</a></h2><p>Автоматизировать извлечение коммерческих лидов из государственных строительных закупок (ЕИС) для поставщиков строительных материалов.</p><p><strong>Что система делает:</strong></p><ol><li>Непрерывно сканирует ЕИС — скачивает документы тендеров</li><li>Разбирает PDF и Excel-сметы через AI — извлекает список материалов</li><li>Сопоставляет позиции смет с номенклатурным каталогом клиента (vector search)</li><li>Ранжирует совпадения и передаёт готовые лиды в CRM клиента</li></ol><p><strong>North Star Metric:</strong> количество верифицированных лидов, переданных в CRM клиентами за последние 30 дней.</p><p><strong>Что НЕ делает (за рамками v1):</strong></p><ul><li>Не является торговой площадкой</li><li>Не ведёт переговоры и не формирует КП</li><li>Не анализирует финансовый результат сделки</li></ul><p><strong>Критерий MVP (первый платящий пилот):</strong> F-CRAWL-1…5 + F-PARSE-1…5 + F-MATCH-1…3, 6 + F-UI-COLL + F-MON-3 (audit trail). Выдача лидов — вручную (без CRM-автоматизации), квоты — вручную. Всё остальное — после пилота.</p><hr><h2 id="_2-роли-пользователеи" tabindex="-1">2. Роли пользователей <a class="header-anchor" href="#_2-роли-пользователеи" aria-label="Permalink to &quot;2. Роли пользователей&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Роль</th><th style="text-align:left;">Описание</th><th style="text-align:left;">Права</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Admin</strong></td><td style="text-align:left;">Внутренний администратор Agelto</td><td style="text-align:left;">Полный доступ: управление кроулерами, PromptRules, прокси, логами</td></tr><tr><td style="text-align:left;"><strong>Client</strong></td><td style="text-align:left;">Менеджер компании-поставщика</td><td style="text-align:left;">Управление своими Коллекциями, просмотр лидов, настройка CRM-интеграции</td></tr><tr><td style="text-align:left;"><strong>Manager</strong></td><td style="text-align:left;">Менеджер по продажам клиента</td><td style="text-align:left;">Просмотр лидов, ручная верификация матчей, отправка в CRM</td></tr><tr><td style="text-align:left;"><strong>Analyst</strong></td><td style="text-align:left;">Премодератор (штат Agelto или клиента — см. [[Открытые вопросы (Agelto)]] P6)</td><td style="text-align:left;">Проверка матчей с confidence &lt; 92% до передачи лида в CRM; вердикты пополняют обучающую выборку</td></tr></tbody></table><hr><h2 id="_3-user-stories" tabindex="-1">3. User Stories <a class="header-anchor" href="#_3-user-stories" aria-label="Permalink to &quot;3. User Stories&quot;">​</a></h2><h3 id="менеджер-по-продажам-client-manager" tabindex="-1">Менеджер по продажам (Client / Manager) <a class="header-anchor" href="#менеджер-по-продажам-client-manager" aria-label="Permalink to &quot;Менеджер по продажам (Client / Manager)&quot;">​</a></h3><ul><li><strong>Как</strong> менеджер, <strong>я хочу</strong> утром открыть дашборд и увидеть список новых тендеров, в сметах которых есть наша номенклатура, <strong>чтобы</strong> не тратить день на ручной поиск по ЕИС</li><li><strong>Как</strong> менеджер, <strong>я хочу</strong> видеть конкретные строки из сметы, которые совпали с нашим каталогом (название, количество, цена, процент совпадения), <strong>чтобы</strong> быстро оценить интерес к тендеру</li><li><strong>Как</strong> менеджер, <strong>я хочу</strong> одним кликом отправить лид в CRM с черновиком КП, <strong>чтобы</strong> не копировать данные вручную</li><li><strong>Как</strong> менеджер, <strong>я хочу</strong> видеть PDF оригинальной сметы с подсветкой найденных позиций, <strong>чтобы</strong> проверить контекст совпадения</li></ul><h3 id="коммерческии-директор-client" tabindex="-1">Коммерческий директор (Client) <a class="header-anchor" href="#коммерческии-директор-client" aria-label="Permalink to &quot;Коммерческий директор (Client)&quot;">​</a></h3><ul><li><strong>Как</strong> коммерческий директор, <strong>я хочу</strong> настроить каталог нашей номенклатуры (Коллекцию) один раз и больше не думать о настройке, <strong>чтобы</strong> система работала автономно</li><li><strong>Как</strong> коммерческий директор, <strong>я хочу</strong> видеть аналитику: сколько лидов найдено, сколько передано в работу, по каким позициям чаще всего совпадения, <strong>чтобы</strong> оценивать эффективность канала</li></ul><h3 id="администратор-платформы" tabindex="-1">Администратор платформы <a class="header-anchor" href="#администратор-платформы" aria-label="Permalink to &quot;Администратор платформы&quot;">​</a></h3><ul><li><strong>Как</strong> администратор, <strong>я хочу</strong> управлять AI-инструкциями через интерфейс без деплоя, <strong>чтобы</strong> быстро корректировать качество парсинга при изменении структуры ЕИС</li></ul><hr><h2 id="_4-функциональные-требования" tabindex="-1">4. Функциональные требования <a class="header-anchor" href="#_4-функциональные-требования" aria-label="Permalink to &quot;4. Функциональные требования&quot;">​</a></h2><h3 id="_4-1-агрегация-тендеров-кроулинг" tabindex="-1">4.1 Агрегация тендеров (Кроулинг) <a class="header-anchor" href="#_4-1-агрегация-тендеров-кроулинг" aria-label="Permalink to &quot;4.1 Агрегация тендеров (Кроулинг)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">Требование</th><th style="text-align:left;">Приоритет</th></tr></thead><tbody><tr><td style="text-align:left;">F-CRAWL-1</td><td style="text-align:left;">Непрерывный мониторинг zakupki.gov.ru: новые тендеры по 44-ФЗ и 223-ФЗ появляются в системе в течение 4 часов после публикации.</td><td style="text-align:left;">🔴 Must Have</td></tr><tr><td style="text-align:left;">F-CRAWL-2</td><td style="text-align:left;">Фильтрация по категориям (ОКПД2), ценовому диапазону, региону, дате подачи заявок — настраивается per-crawler.</td><td style="text-align:left;">🔴 Must Have</td></tr><tr><td style="text-align:left;">F-CRAWL-3</td><td style="text-align:left;">Скачивание прикреплённых документов (PDF, Excel, ZIP) с ротацией прокси.</td><td style="text-align:left;">🔴 Must Have</td></tr><tr><td style="text-align:left;">F-CRAWL-4</td><td style="text-align:left;">Устойчивость к сбоям: при ошибке кроулер возобновляет работу с последнего успешного состояния (keepStateOnCrash).</td><td style="text-align:left;">🔴 Must Have</td></tr><tr><td style="text-align:left;">F-CRAWL-5</td><td style="text-align:left;">Дедупликация тендеров: повторная публикация тендера с тем же <code>reg_number</code> обновляет существующую запись, не создаёт дубликат.</td><td style="text-align:left;">🔴 Must Have</td></tr></tbody></table><h3 id="_4-2-ai-анализ-документов-парсинг" tabindex="-1">4.2 AI-анализ документов (Парсинг) <a class="header-anchor" href="#_4-2-ai-анализ-документов-парсинг" aria-label="Permalink to &quot;4.2 AI-анализ документов (Парсинг)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">Требование</th><th style="text-align:left;">Приоритет</th></tr></thead><tbody><tr><td style="text-align:left;">F-PARSE-1</td><td style="text-align:left;">Автоматическое определение: содержит ли документ строительную смету. Документы без сметы не проходят детальный парсинг (экономия токенов).</td><td style="text-align:left;">🔴 Must Have</td></tr><tr><td style="text-align:left;">F-PARSE-2</td><td style="text-align:left;">Детальное извлечение позиций сметы из PDF: название материала, единица измерения, количество, цена за единицу, ОКПД2 (при наличии).</td><td style="text-align:left;">🔴 Must Have</td></tr><tr><td style="text-align:left;">F-PARSE-3</td><td style="text-align:left;">Детальное извлечение позиций сметы из Excel (форматы строительных смет РФ).</td><td style="text-align:left;">🔴 Must Have</td></tr><tr><td style="text-align:left;">F-PARSE-4</td><td style="text-align:left;">Управление AI-инструкциями (PromptRules) через Filament без деплоя — для оперативной реакции на изменения структуры ЕИС.</td><td style="text-align:left;">🔴 Must Have</td></tr><tr><td style="text-align:left;">F-PARSE-5</td><td style="text-align:left;">Retry-механизм: при ошибке AI (rate limit, timeout) задача повторяется с exponential backoff. До 5 попыток для AI-скрининга, до 3 — для подготовки документа и детального парсинга (синхронизировано с кодом).</td><td style="text-align:left;">🔴 Must Have</td></tr></tbody></table><h3 id="_4-3-семантическии-матчинг" tabindex="-1">4.3 Семантический матчинг <a class="header-anchor" href="#_4-3-семантическии-матчинг" aria-label="Permalink to &quot;4.3 Семантический матчинг&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">Матчинг идёт через внешний эталон ([[ADR-001_Catalog_From_TcenZor|ADR-001]])</p><p>Позиция сметы сопоставляется не напрямую с коллекцией клиента, а через <strong>эталонный товар каталога [[TcenZor]]</strong> (категории/эталоны/алиасы/нормативка). Эталон — внешний, приходит по API ([[Universal_Catalog_Architecture]]).</p></div><table tabindex="0"><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">Требование</th><th style="text-align:left;">Приоритет</th></tr></thead><tbody><tr><td style="text-align:left;">F-MATCH-0</td><td style="text-align:left;">Эталонный строительный каталог (категории/эталоны/алиасы/ГОСТ·ОКПД2·КТРУ) синхронизируется из [[TcenZor]] по API в локальную реплику. Матчинг позиции сметы → эталон → коллекция клиента.</td><td style="text-align:left;">🔴 Must Have</td></tr><tr><td style="text-align:left;">F-MATCH-1</td><td style="text-align:left;">Клиент загружает свою номенклатуру (Коллекцию): SKU, наименование, единица, цена. Валидация импорта: дубли SKU, пустые наименования/единицы, нечисловые цены → отчёт об ошибках, невалидные строки не индексируются.</td><td style="text-align:left;">🔴 Must Have</td></tr><tr><td style="text-align:left;">F-MATCH-2</td><td style="text-align:left;">Система автоматически строит векторные представления (embeddings) для каждой позиции Коллекции.</td><td style="text-align:left;">🔴 Must Have</td></tr><tr><td style="text-align:left;">F-MATCH-3</td><td style="text-align:left;">Семантическое сопоставление позиций сметы с Коллекцией: Match Score (0–1), лучший кандидат (топ-1) для каждой позиции.</td><td style="text-align:left;">🔴 Must Have</td></tr><tr><td style="text-align:left;">F-MATCH-3a</td><td style="text-align:left;">Топ-3 кандидата на позицию (выбор менеджером при верификации).</td><td style="text-align:left;">🟡 Should Have</td></tr><tr><td style="text-align:left;">F-MATCH-4</td><td style="text-align:left;">Hard Constraints Validation: после векторного матчинга — проверка совместимости единиц измерения. Несовместимые пары (т vs м²) получают флаг <code>unit_mismatch</code>.</td><td style="text-align:left;">🟡 Should Have</td></tr><tr><td style="text-align:left;">F-MATCH-5</td><td style="text-align:left;">Ручная верификация: менеджер подтверждает или отклоняет каждый матч. Подтверждённые матчи улучшают качество модели (self-learning).</td><td style="text-align:left;">🟡 Should Have</td></tr><tr><td style="text-align:left;">F-MATCH-6</td><td style="text-align:left;">Human-in-the-loop: матчи с confidence &lt; 92% не передаются в CRM автоматически — помечаются «Требует проверки» и уходят на премодерацию роли Analyst. Порог настраивается per-клиент.</td><td style="text-align:left;">🔴 Must Have</td></tr><tr><td style="text-align:left;">F-MATCH-7</td><td style="text-align:left;">Active learning: вердикты верификации (подтверждено/отклонено) сохраняются как размеченная обучающая выборка. Периодичность дообучения / переиндексации — TBD ([[Открытые вопросы (Agelto)]]).</td><td style="text-align:left;">🟡 Should Have</td></tr></tbody></table><h3 id="_4-4-скоринг-и-приоритизация-лидов" tabindex="-1">4.4 Скоринг и приоритизация лидов <a class="header-anchor" href="#_4-4-скоринг-и-приоритизация-лидов" aria-label="Permalink to &quot;4.4 Скоринг и приоритизация лидов&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">Требование</th><th style="text-align:left;">Приоритет</th></tr></thead><tbody><tr><td style="text-align:left;">F-SCORE-1</td><td style="text-align:left;">Итоговый Score лида: взвешенная сумма — Match Score позиций, доля от начальной цены тендера, срок подачи заявок, регион. <strong>Draft-формула v0 (требует калибровки на пилоте):</strong> <code>Score = 0.5·avg(MatchScore совпавших позиций) + 0.25·norm(Σ цена совпавших позиций / НМЦК) + 0.15·norm(дней до дедлайна, cap 30) + 0.10·region_match</code>. Все компоненты нормированы в [0,1].</td><td style="text-align:left;">🟡 Should Have</td></tr><tr><td style="text-align:left;">F-SCORE-2</td><td style="text-align:left;">Автоматическая фильтрация: лиды с Score &lt; порога (настраивается клиентом) не отображаются в Radar.</td><td style="text-align:left;">🟡 Should Have</td></tr></tbody></table><h3 id="_4-5-crm-интеграция" tabindex="-1">4.5 CRM-интеграция <a class="header-anchor" href="#_4-5-crm-интеграция" aria-label="Permalink to &quot;4.5 CRM-интеграция&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">Требование</th><th style="text-align:left;">Приоритет</th></tr></thead><tbody><tr><td style="text-align:left;">F-CRM-1</td><td style="text-align:left;">Одним кликом — отправка лида в CRM клиента (Bitrix24, amoCRM) с автоматическим созданием Сделки.</td><td style="text-align:left;">🟡 Should Have</td></tr><tr><td style="text-align:left;">F-CRM-2</td><td style="text-align:left;">Прикрепление к Сделке: ссылка на тендер ЕИС, срок подачи, начальная цена, список совпадающих позиций с Match Score.</td><td style="text-align:left;">🟡 Should Have</td></tr><tr><td style="text-align:left;">F-CRM-3</td><td style="text-align:left;">Webhook-уведомление клиенту при появлении нового лида с Score выше настроенного порога.</td><td style="text-align:left;">🟡 Should Have</td></tr><tr><td style="text-align:left;">F-CRM-4</td><td style="text-align:left;">Контракт интеграции: отправка идемпотентна (повторная отправка лида не создаёт дубль Сделки — ключ: reg_number + client_id), ошибки CRM API ретраятся с backoff (до 3 попыток), после исчерпания — лид помечается <code>crm_export_failed</code> с уведомлением клиенту.</td><td style="text-align:left;">🟡 Should Have</td></tr></tbody></table><h3 id="_4-6-пользовательскии-интерфеис" tabindex="-1">4.6 Пользовательский интерфейс <a class="header-anchor" href="#_4-6-пользовательскии-интерфеис" aria-label="Permalink to &quot;4.6 Пользовательский интерфейс&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">Требование</th><th style="text-align:left;">Приоритет</th></tr></thead><tbody><tr><td style="text-align:left;">F-UI-RADAR</td><td style="text-align:left;">Radar: дашборд новых тендеров с Match Score в реальном времени. Фильтры по региону, дате, Score.</td><td style="text-align:left;">🟡 Should Have</td></tr><tr><td style="text-align:left;">F-UI-SMETA</td><td style="text-align:left;">Smeta Viewer: PDF-вьюер с подсветкой найденных в смете позиций Коллекции клиента.</td><td style="text-align:left;">🟡 Should Have</td></tr><tr><td style="text-align:left;">F-UI-COLL</td><td style="text-align:left;">Collections: CRUD-управление каталогом номенклатуры клиента (импорт из Excel/CSV, ручное редактирование).</td><td style="text-align:left;">🔴 Must Have</td></tr><tr><td style="text-align:left;">F-UI-LEADS</td><td style="text-align:left;">Leads: список верифицированных лидов, статусы, кнопка отправки в CRM.</td><td style="text-align:left;">🟡 Should Have</td></tr><tr><td style="text-align:left;">F-UI-ANALYTICS</td><td style="text-align:left;">Analytics: статистика парсинга, матчинга, конверсии лидов.</td><td style="text-align:left;">🟢 Nice to Have</td></tr></tbody></table><h3 id="_4-7-справочники-и-мастер-данные-mdm" tabindex="-1">4.7 Справочники и мастер-данные (MDM) <a class="header-anchor" href="#_4-7-справочники-и-мастер-данные-mdm" aria-label="Permalink to &quot;4.7 Справочники и мастер-данные (MDM)&quot;">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">Эталонный каталог и нормативка — потребляются из [[TcenZor]]</p><p>По [[ADR-001_Catalog_From_TcenZor|ADR-001]] Agelto <strong>не строит</strong> собственный эталонный MDM. Нормативка (ГОСТ/ОКПД2/КТРУ/КСР) и эталонные товары ведутся в каталоге-хабе [[TcenZor]] и приходят по API. Внутри Agelto остаётся только <strong>golden dataset вердиктов</strong> (F-MDM-3) — это и есть барьер входа Agelto.</p></div><table tabindex="0"><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">Требование</th><th style="text-align:left;">Приоритет</th></tr></thead><tbody><tr><td style="text-align:left;">F-MDM-1</td><td style="text-align:left;">Эталонный каталог + нормативка (КТРУ/КСР/ГОСТ/ОКПД2) <strong>потребляются из [[TcenZor]]</strong> по API в локальную реплику (см. F-MATCH-0). Agelto использует их как эталон при матчинге, но не ведёт сам.</td><td style="text-align:left;">🟡 Should Have</td></tr><tr><td style="text-align:left;">F-MDM-2</td><td style="text-align:left;">Синхронизация реплики каталога из TcenZor: инкрементально по <code>updated_at</code> + поведение при недоступности хаба (работа по последней реплике). Контракт: [[Universal_Catalog_Architecture]].</td><td style="text-align:left;">🟡 Should Have</td></tr><tr><td style="text-align:left;">F-MDM-3</td><td style="text-align:left;">Обучающая коллекция: размеченные строки смет (цель диплома: 50 000+) накапливаются из вердиктов верификации (F-MATCH-7) и используются для контроля качества. <strong>Ключевой актив Agelto</strong> (барьер входа после переноса каталога в TcenZor).</td><td style="text-align:left;">🟢 Nice to Have</td></tr></tbody></table><h3 id="_4-8-лингвистическии-комплаенс-v2" tabindex="-1">4.8 Лингвистический комплаенс (v2) <a class="header-anchor" href="#_4-8-лингвистическии-комплаенс-v2" aria-label="Permalink to &quot;4.8 Лингвистический комплаенс (v2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">Требование</th><th style="text-align:left;">Приоритет</th></tr></thead><tbody><tr><td style="text-align:left;">F-LANG-1</td><td style="text-align:left;">Матчинг латинских брендов с кириллическими эквивалентами (мультиязычные embeddings) — требование закона о кириллизации коммерческих обозначений 2025–2026 (обоснование: диплом гл. 1.3, архив в <code>assets/</code>). Явно отложено в v2, фиксируется чтобы не потерять.</td><td style="text-align:left;">🟢 Could Have (v2)</td></tr></tbody></table><hr><h2 id="_5-нефункциональные-требования" tabindex="-1">5. Нефункциональные требования <a class="header-anchor" href="#_5-нефункциональные-требования" aria-label="Permalink to &quot;5. Нефункциональные требования&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Требование</th><th style="text-align:left;">Значение</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Точность матчинга (Accuracy)</strong></td><td style="text-align:left;">≥ 92% подтверждённых матчей (цель диплома: 92–95%). Методика: golden dataset из эталонных смет + выборочная ручная проверка N смет/мес. Позиции с confidence &lt; 92% — премодерация (F-MATCH-6).</td></tr><tr><td style="text-align:left;"><strong>Скорость AI-скрининга</strong></td><td style="text-align:left;">Один документ — в течение 5 мин от постановки в очередь (таймауты кода: подготовка 300 сек + скрининг 180 сек, без учёта глубины очереди)</td></tr><tr><td style="text-align:left;"><strong>Скорость полного парсинга сметы</strong></td><td style="text-align:left;">Один документ — в течение 15 мин после скрининга (чанковая обработка по 80 строк)</td></tr><tr><td style="text-align:left;"><strong>Скорость матчинга</strong></td><td style="text-align:left;">Один тендер (~100 позиций) — в течение 30 сек после завершения парсинга</td></tr><tr><td style="text-align:left;"><strong>Uptime</strong></td><td style="text-align:left;">99% в рабочие часы (пн-пт 8:00–20:00 МСК)</td></tr><tr><td style="text-align:left;"><strong>Freshness тендеров</strong></td><td style="text-align:left;">Новые тендеры из ЕИС — в системе в течение 4 часов</td></tr><tr><td style="text-align:left;"><strong>Изоляция данных клиентов</strong></td><td style="text-align:left;">Коллекции и лиды клиента A не видны клиенту B. ⚠️ Механизм (RLS / tenant_id / схемы) не выбран — см. [[Открытые вопросы (Agelto)]] T4; мультитенантность в коде не начата.</td></tr><tr><td style="text-align:left;"><strong>Безопасность PromptRules</strong></td><td style="text-align:left;">Изменение AI-инструкций только для роли Admin. Версионирование — rollback при деградации качества.</td></tr><tr><td style="text-align:left;"><strong>Хранение ПД</strong></td><td style="text-align:left;">Серверы в РФ, ФЗ-152 (контактные данные ИНН/КПП заказчиков — публичные данные ЕИС, не ПД физлиц). ⚠️ Оговорка: документы тендеров отправляются в Google Gemini API — данные покидают РФ; резолюция обязательна ([[Открытые вопросы (Agelto)]] L3, [[Risk_Register (Agelto)]] R-5).</td></tr><tr><td style="text-align:left;"><strong>RPO / RTO</strong></td><td style="text-align:left;">TBD — целевые значения не определены ([[Открытые вопросы (Agelto)]] T7)</td></tr></tbody></table><hr><h2 id="_6-граничные-случаи-и-особые-сценарии" tabindex="-1">6. Граничные случаи и особые сценарии <a class="header-anchor" href="#_6-граничные-случаи-и-особые-сценарии" aria-label="Permalink to &quot;6. Граничные случаи и особые сценарии&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Сценарий</th><th style="text-align:left;">Требуемое поведение</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>ЕИС изменил структуру HTML</strong></td><td style="text-align:left;">Кроулер перестаёт находить данные → метрика <code>items_count = 0</code> за &gt;2 часа → Alert администратору. PromptRules корректируется без деплоя.</td></tr><tr><td style="text-align:left;"><strong>Документ — скан без текстового слоя</strong></td><td style="text-align:left;">Gemini возвращает <code>has_smeta: false</code> → задача помечается <code>ocr_required</code> → помещается в очередь для LayoutLMv3 (v2). В v1 — логируется, не парсится.</td></tr><tr><td style="text-align:left;"><strong>Позиция сметы — нестандартная единица измерения</strong></td><td style="text-align:left;">Hard Constraints флагирует как <code>unit_unknown</code>. Матч остаётся с пониженным Score и пометкой для ручной проверки.</td></tr><tr><td style="text-align:left;"><strong>Клиент удалил позицию из Коллекции</strong></td><td style="text-align:left;">Все исторические матчи с этой позицией сохраняются (soft delete). Новые матчи не создаются.</td></tr><tr><td style="text-align:left;"><strong>Тендер снят с публикации на ЕИС</strong></td><td style="text-align:left;">Статус тендера обновляется при следующем сканировании. Уже переданные в CRM лиды не отзываются — уведомление клиенту.</td></tr><tr><td style="text-align:left;"><strong>Gemini API недоступен &gt; 30 мин</strong></td><td style="text-align:left;">Задачи накапливаются в очереди <code>parsing</code>. Администратор уведомляется через Telegram-бот. При восстановлении — автоматический retry.</td></tr><tr><td style="text-align:left;"><strong>Коллекция клиента содержит &gt;10 000 позиций</strong></td><td style="text-align:left;">Векторный индекс строится в фоне (async job). Матчинг запускается только после завершения индексации. Клиент видит статус «Коллекция обновляется».</td></tr><tr><td style="text-align:left;"><strong>Матч с confidence &lt; 92%</strong></td><td style="text-align:left;">Лид не уходит в CRM автоматически: флаг «Требует проверки» → очередь премодерации Analyst (F-MATCH-6).</td></tr><tr><td style="text-align:left;"><strong>Превышение квоты / rate limit Gemini</strong></td><td style="text-align:left;">Задачи остаются в очереди (exponential backoff, до 5 попыток скрининга). При систематическом превышении — алерт администратору и приостановка постановки новых задач.</td></tr><tr><td style="text-align:left;"><strong>Сбой стадии пайплайна</strong></td><td style="text-align:left;">State machine переводит документ в failed-статус (<code>PrimaryAnalysisFailed</code> / <code>EstimateAnalysisFailed</code> / <code>Error</code>), переход логируется, администратор получает Telegram-уведомление. ✅ Реализовано в коде.</td></tr></tbody></table><hr><h2 id="_7-монетизация-—-требования-к-системе" tabindex="-1">7. Монетизация — требования к системе <a class="header-anchor" href="#_7-монетизация-—-требования-к-системе" aria-label="Permalink to &quot;7. Монетизация — требования к системе&quot;">​</a></h2><h3 id="_7-1-тарифная-сетка-обоснование-и-финмодель-03-financial-model" tabindex="-1">7.1 Тарифная сетка (обоснование и финмодель: [[03_Financial_Model]]) <a class="header-anchor" href="#_7-1-тарифная-сетка-обоснование-и-финмодель-03-financial-model" aria-label="Permalink to &quot;7.1 Тарифная сетка (обоснование и финмодель: [[03_Financial_Model]])&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Тариф</th><th style="text-align:left;">Целевая аудитория</th><th style="text-align:left;">Лимиты и функции</th><th style="text-align:left;">Цена/мес</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Start</strong></td><td style="text-align:left;">Малый бизнес, ИП, узкопрофильные поставщики</td><td style="text-align:left;">До 50 декомпозированных смет/мес, Telegram-уведомления, базовый поиск</td><td style="text-align:left;">25 000 ₽</td></tr><tr><td style="text-align:left;"><strong>Business</strong></td><td style="text-align:left;">Средние производственные компании, дистрибьюторы</td><td style="text-align:left;">До 300 смет/мес, CRM-интеграция, расширенный скоринг, матчинг по КСР</td><td style="text-align:left;">75 000 ₽</td></tr><tr><td style="text-align:left;"><strong>Enterprise</strong></td><td style="text-align:left;">Заводы-изготовители, холдинги</td><td style="text-align:left;">Безлимит, API-доступ, выделенный сервер, персональный алгоритм матчинга</td><td style="text-align:left;">от 200 000 ₽</td></tr></tbody></table><p>Доходные потоки: подписка (MRR) + usage-based сверх лимита (pay-per-lead) + Setup Service. ⚠️ Себестоимость AI-обработки одной сметы не посчитана — маржа тарифов не подтверждена ([[Risk_Register (Agelto)]] R-7).</p><h3 id="_7-2-требования" tabindex="-1">7.2 Требования <a class="header-anchor" href="#_7-2-требования" aria-label="Permalink to &quot;7.2 Требования&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Требование</th><th style="text-align:left;">Описание</th><th style="text-align:left;">Приоритет</th></tr></thead><tbody><tr><td style="text-align:left;">F-MON-1</td><td style="text-align:left;">Счётчик смет/месяц на клиента: система ведёт учёт количества проанализированных документов. Превышение тарифного лимита → задачи блокируются до следующего периода или upgrade. На пилотной фазе контроль лимитов — вручную; автоматизация обязательна к публичному запуску.</td><td style="text-align:left;">🟡 Should Have (пилот) → 🔴 Must Have (запуск)</td></tr><tr><td style="text-align:left;">F-MON-2</td><td style="text-align:left;">Freemium: ⚠️ три несогласованные версии — «1 Коллекция / 50 позиций / 5 лидов» (здесь), «3 первые позиции каждой сметы» (Freemium Light, [[03_Financial_Model]] §1), «лимит открыт» (P2). Единая модель — [[Открытые вопросы (Agelto)]] P5. До резолюции не реализовывать; для пилотной фазы freemium не нужен.</td><td style="text-align:left;">🟢 Could Have</td></tr><tr><td style="text-align:left;">F-MON-3</td><td style="text-align:left;">Audit trail использования: лог всех AI-запросов с client_id, документом, датой — для верификации биллинга.</td><td style="text-align:left;">🔴 Must Have</td></tr><tr><td style="text-align:left;">F-MON-4</td><td style="text-align:left;">Setup Service: платная разовая услуга — интеграция «под ключ» (CRM, загрузка коллекции, обучение персонала). Главная митигация churn-риска ([[Risk_Register (Agelto)]] R-3).</td><td style="text-align:left;">🟡 Should Have</td></tr></tbody></table><hr><h2 id="_8-вне-скоупа-явно-не-в-проекте" tabindex="-1">8. Вне скоупа (явно НЕ в проекте) <a class="header-anchor" href="#_8-вне-скоупа-явно-не-в-проекте" aria-label="Permalink to &quot;8. Вне скоупа (явно НЕ в проекте)&quot;">​</a></h2><ul><li>❌ Участие в тендерах (подача заявок) — другой продукт</li><li>❌ Анализ тендеров за пределами ЕИС (коммерческие тендеры, В2В-закупки) — v2+</li><li>❌ Автоматическое формирование КП — только данные для КП, не сам документ</li><li>❌ Финансовый анализ результатов сделки — задача AiFina</li><li>❌ Международные закупки (не zakupki.gov.ru) — за пределами целевого рынка</li></ul><hr><h2 id="_9-открытые-архитектурные-вопросы" tabindex="-1">9. Открытые архитектурные вопросы <a class="header-anchor" href="#_9-открытые-архитектурные-вопросы" aria-label="Permalink to &quot;9. Открытые архитектурные вопросы&quot;">​</a></h2><p>→ Полный список технических вопросов: [[Architecture_Agelto#15. Открытые архитектурные вопросы]] → Реестр рисков: [[Risk_Register (Agelto)]]</p><blockquote><p>Аудит ТЗ проведён 2026-06-11: находки внесены в этот документ (приоритеты, критерий MVP, NFR, F-MATCH-6/7, F-MDM, F-LANG, тарифы), в [[Architecture_Agelto]] (синхронизация с кодом, QA PromptRules, observability/DR), [[Risk_Register (Agelto)]], [[Onboarding]], [[Lead_Verification]] и [[Открытые вопросы (Agelto)]] (T5–T9, P5–P6, L3).</p></blockquote><p>Бизнес-критические:</p><ul><li>Нужна ли интеграция с FTP XML feeds ЕИС для большей надёжности агрегации?</li><li>Как тарифицировать AI-запросы: по количеству смет или по количеству лидов?</li><li>Нужен ли доступ к API для Enterprise-клиентов с первой версии?</li></ul>',65)])])}const y=e(r,[["render",n]]);export{x as __pageData,y as default};
